-- Data induk UPT: 492 menjadi 531 unit.
--
-- Dihasilkan oleh tools/susun-master-upt.mjs dari data/sumber/daftar-upt-nasional.csv
-- (613 baris, 1 di antaranya kembar) dikurangi Bapas dan Rumah Sakit
-- Pengayoman. Potret lengkapnya ada di data/master-upt.csv.
--
-- 39 unit ditambahkan, 32 di antaranya seluruh LPKA di Indonesia —
-- sampai migrasi ini tidak ada satu pun LPKA di data induk, sehingga setiap
-- berita tentang anak yang berhadapan dengan hukum selalu berakhir
-- "Belum Teridentifikasi".
--
-- Tidak ada baris yang dihapus. Empat unit yang naik status dari Rutan menjadi
-- Lapas diganti namanya, dan berita serta penugasan pengguna yang menunjuk nama
-- lama ikut diperbarui pada transaksi yang sama.
--
-- Koordinat 39 unit baru diwarisi dari unit terdekat dan ditandai demikian.
-- Tidak satu pun di antaranya alamat gedung; seluruhnya menunggu verifikasi
-- Super Admin, sama seperti 491 unit lama.

begin;

-- 1. Unit yang naik status dari Rutan menjadi Lapas. Dijalankan lebih dulu
--    supaya penyisipan di bawah mengenali mereka lewat nama barunya, bukan
--    menyisipkan unit kembar.

update public.upt       set nama_upt     = 'Lapas Kelas IIB Wonosari', jenis_upt = 'Lapas', updated_at = now()
                        where nama_upt   = 'Rutan Kelas IIB Wonosari';
update public.berita    set nama_upt     = 'Lapas Kelas IIB Wonosari' where nama_upt     = 'Rutan Kelas IIB Wonosari';
update public.app_users set assigned_upt = 'Lapas Kelas IIB Wonosari' where assigned_upt = 'Rutan Kelas IIB Wonosari';
update public.upt       set nama_upt     = 'Lapas Kelas IIB Batang', jenis_upt = 'Lapas', updated_at = now()
                        where nama_upt   = 'Rutan Kelas IIB Batang';
update public.berita    set nama_upt     = 'Lapas Kelas IIB Batang' where nama_upt     = 'Rutan Kelas IIB Batang';
update public.app_users set assigned_upt = 'Lapas Kelas IIB Batang' where assigned_upt = 'Rutan Kelas IIB Batang';
update public.upt       set nama_upt     = 'Lapas Kelas IIB Purwodadi', jenis_upt = 'Lapas', updated_at = now()
                        where nama_upt   = 'Rutan Kelas IIB Purwodadi';
update public.berita    set nama_upt     = 'Lapas Kelas IIB Purwodadi' where nama_upt     = 'Rutan Kelas IIB Purwodadi';
update public.app_users set assigned_upt = 'Lapas Kelas IIB Purwodadi' where assigned_upt = 'Rutan Kelas IIB Purwodadi';
update public.upt       set nama_upt     = 'Lapas Kelas IIB Wonogiri', jenis_upt = 'Lapas', updated_at = now()
                        where nama_upt   = 'Rutan Kelas IIB Wonogiri';
update public.berita    set nama_upt     = 'Lapas Kelas IIB Wonogiri' where nama_upt     = 'Rutan Kelas IIB Wonogiri';
update public.app_users set assigned_upt = 'Lapas Kelas IIB Wonogiri' where assigned_upt = 'Rutan Kelas IIB Wonogiri';

-- 2. Unit yang belum ada di data induk. Klausa "on conflict do nothing" membuat
--    migrasi ini aman dijalankan dua kali, dan membuatnya tidak pernah menimpa
--    koordinat yang sudah diperbaiki tangan.
