  nama_upt, jenis_upt, kelas_upt, subjenis_upt, provinsi, kanwil, kabupaten_kota,
  latitude, longitude, coordinate_quality, coordinate_source, coordinate_score,
  location_hint, catatan_verifikasi, aktif
)
